const fetch = require('node-fetch');
const fs = require('fs');

async function mintNFT() {
  const url = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';

  const options = {
    method: 'POST',
    headers: {
      accept: 'application/json',
      'content-type': 'application/json',
      'x-api-key': 'sk_test_12345'
    },
    body: JSON.stringify({
      recipient: 'email:user@example.com:polygon-amoy',
      metadata: {
        name: 'Crossmint Example NFT',
        image: 'https://www.crossmint.com/assets/crossmint/logo.png',
        description: 'My NFT created via the minting API!'
      }
    })
  };

  try {
    const response = await fetch(url, options);
    const data = await response.json();
    fs.writeFileSync('/home/user/fixed_mint_response.json', JSON.stringify(data, null, 2));
  } catch (err) {
    fs.writeFileSync('/home/user/fixed_mint_response.json', JSON.stringify({ error: err.message }, null, 2));
  }
}

mintNFT();

